class Config {
  // eslint-disable-next-line class-methods-use-this
  _getEnvVar(varName, defaultValue) {
    return process.env[varName] || defaultValue;
  }

  get environment() {
    return this._getEnvVar('NODE_ENV', 'development');
  }

  get contactEmail() {
    return this._getEnvVar('REACT_APP_CONTACT_EMAIL', 'ofir@ofiryaron.com');
  }

  get GaTrackingId() {
    return this._getEnvVar('REACT_APP_GA_TRACKING_ID', '');
  }
}

const config = new Config();
export default config;
